import { BRAND } from '@/branding/brand'
import { cn } from '@/lib/utils'
import { useTheme } from '@/themes'

const assetPath = (path: string) => `${import.meta.env.BASE_URL}${path.replace(/^\/+/, '')}`

// Brand badge: the nous-girl mark in the app-icon squircle, theme-aware —
// light mode shows the black girl on the white squircle, dark mode the white
// girl on the #0d1117 squircle. The mark PNG carries the rounded shape and
// transparent corners, so no tile/rounding classes here. Generated by
// scripts/generate_icons.py from the girl SVGs + squircle backgrounds; size
// via className (default size-14).
export function BrandMark({ className, ...props }: React.ComponentProps<'span'>) {
  const { renderedMode } = useTheme()
  const dark = renderedMode === 'dark'

  // CORTA CUSTOMIZATION: the mark comes from the brand. A brand without a
  // supplied mark renders none rather than another brand's (or an invented) one.
  if (!BRAND.mark) {
    return null
  }

  return (
    <span className={cn('inline-flex size-14 shrink-0 items-center justify-center', className)} {...props}>
      <img alt="" className="size-full object-contain" src={assetPath(dark ? BRAND.mark.dark : BRAND.mark.light)} />
    </span>
  )
}

// CORTA CUSTOMIZATION: the brand's logotype, theme-aware like the mark. Renders
// nothing for a brand without one (upstream keeps its "HERMES AGENT" lettering).
export function BrandLogo({ className, ...props }: React.ComponentProps<'img'>) {
  const { renderedMode } = useTheme()

  if (!BRAND.logo) {
    return null
  }

  return (
    <img
      alt={BRAND.productName}
      className={cn('mx-auto block h-auto', className)}
      src={assetPath(renderedMode === 'dark' ? BRAND.logo.dark : BRAND.logo.light)}
      {...props}
    />
  )
}
